function jobMetrics(j){return `<div class="job-metrics"><span>Доход <b>${j.pay}</b> усл. ед./квартал</span><span><b>${j.hours}</b> ч/нед.</span><span>Дорога <b>${j.commute}</b> мин</span><span>Нагрузка <b>${j.load}/100</b></span><span>Коллектив: ${esc(j.team)}</span></div>`;}
function careerChoiceView(p){return `<div class="chapter-line"><span>РАБОТА И ОБУЧЕНИЕ</span><span>ВРЕМЯ НА ПАУЗЕ</span></div><h2 class="event-title">${esc(p.title)}</h2><p class="event-desc">${esc(p.text)}</p><div class="choices">${p.options.map((o,i)=>decisionButton('career',i,o.title,o.job?`<span class="job-metrics compact-job">${o.job.pay} усл. ед. · ${o.job.hours} ч/нед. · нагрузка ${o.job.load}</span>`:esc(LifeChoiceCopy.careerHint(p,o)),o.disabled)).join('')}</div>`;}
function careerPanel(){if(state.age<17)return '';const c=LifeCareer.ensure(state),j=c.currentJob,blocked=state.ended||Boolean(F.pending(state)),wait=Math.max(0,c.searchAfter-F.ensure(state).months);return `<section class="habits-panel career-panel"><h3>Работа и обучение</h3>${j?`<p><strong>${esc(j.title)}</strong><br>${esc(j.employer)}</p>${jobMetrics(j)}<p class="tiny">Опыт направления: ${(c.experience[j.field]/12).toLocaleString('ru-RU',{maximumFractionDigits:1})} г.${c.interests.includes(j.field)?' · знакомый интерес':''}</p>`:'<p>Постоянная работа пока не выбрана.</p>'}${c.training?`<p>Учёба: ${esc(LifeCareer.fields[c.training.field].name)}<br><small>Осталось ${c.training.remaining} мес. из ${c.training.total}</small></p>`:''}${c.project?`<p class="tiny">Личный проект · ${c.project.months} мес.</p>`:''}${state.age>=18?`<div class="career-actions"><button data-career-action="jobs" ${blocked||wait?'disabled':''}>${wait?'Новая подборка через '+wait+' мес.':'Посмотреть работу'}</button><button data-career-action="retrain" ${blocked?'disabled':''}>Переучиться</button><button data-career-action="balance" ${blocked?'disabled':''}>Изменить нагрузку</button><button data-career-action="self" ${blocked?'disabled':''}>Своё дело</button></div><div class="career-goal"><span>Ближайшая рабочая цель</span><p>${c.goal?esc(c.goal.name)+(c.goal.done?' · выполнена':''):'Можно выбрать направление для ближайшего периода.'}</p><button data-career-goal-picker>Выбрать или изменить цель</button></div>`:''}</section>`;}
function careerGoalPicker(){const c=LifeCareer.ensure(state);openDialog(`<span class="eyebrow">РАБОЧАЯ ЦЕЛЬ</span><h2>Что сейчас важнее?</h2><p>Цель можно изменить. Она помогает выбрать направление и не требует повышаться любой ценой.</p>${[['find','Найти подходящую работу'],['train','Освоить новое направление'],['promote','Выбрать следующий шаг в профессии'],['balance','Найти более посильный график']].map(([key,title])=>`<button class="secondary goal-action" data-set-career-goal="${key}">${title}${c.goal?.type===key?' · выбрана':''}</button>`).join('')}`);document.querySelectorAll('[data-set-career-goal]').forEach(b=>b.onclick=()=>{LifeCareer.setGoal(state,b.dataset.setCareerGoal);$('#dialog').close();save();render();});}
function bindCareer(){document.querySelectorAll('[data-career]').forEach(b=>b.onclick=()=>{if(F.resolve(state,Number(b.dataset.career))){save();render();}});document.querySelectorAll('[data-career-action]').forEach(b=>b.onclick=()=>{if(!F.pending(state)&&LifeCareer.request(state,b.dataset.careerAction)){save();render();}});document.querySelectorAll('[data-career-goal-picker]').forEach(b=>b.onclick=careerGoalPicker);}
function startCareerTrial(s,topic){
 const c=LifeCareer.ensure(s);c.lastMonth=s.flow.months;c.seen=['school','internship'];c.desiredField='design';c.interests=['design'];c.searchAfter=0;c.active=null;c.currentJob=null;c.training=null;c.job='Поиск работы';c.nextReview=s.flow.months+18;
 if(['switch','promotion','balance','self','retrain'].includes(topic)){LifeCareer.offer(s,'jobs');const selection=c.active.options[topic==='balance'?1:0];LifeCareer.resolve(s,c.active.options.indexOf(selection));c.active=null;c.searchAfter=0;c.experience.design=24;}
 if(topic==='internship'){c.route='education';c.training={field:'design',remaining:18,total:36,kind:'degree'};}
 const target=topic==='switch'?'jobs':topic;
 LifeCareer.offer(s,target);
}
